const resp = $input.first().json;
const aiText = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';
let jsonText = aiText.trim().replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/\s*```$/, '');
// 2026-08-03 事故：Gemini 在合法 JSON 後面又吐一長串重複垃圾，整段 parse 不動；
// 舊版 catch 直接把「整包原始 JSON」當文案送去發文，兩篇爛貼文掛在粉專（一篇 4 天沒人發現）。
// 現在三層：正常 parse → 正則救回兩個欄位 → 都失敗就留空，交給守門員擋下，絕不硬發。
const pick = (src2, key) => {
  const m = src2.match(new RegExp('"' + key + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"'));
  if (!m) return '';
  try { return JSON.parse('"' + m[1] + '"'); } catch (e) { return ''; }
};
let parsed;
let 救援 = false;
try {
  parsed = JSON.parse(jsonText);
} catch (e) {
  parsed = { 粉專主體: pick(jsonText, '粉專主體'), 社團主體: pick(jsonText, '社團主體') };
  救援 = true;
}
const src = $('永慶官網補資料').first().json;
// 鎖價後處理：文案內非官方總價的價格字串，替換回官方值
const price = src['總價萬'];
let body = String(parsed['粉專主體'] || '').trim();
if (price) {
  const aiNum = (body.match(/(\d{3,7})\s*萬/) || [])[1];
  if (aiNum && Number(aiNum) !== Number(price)) body = body.split(aiNum + ' 萬').join(price + ' 萬').split(aiNum + '萬').join(price + '萬');
}
const 粉專footer = '\n\n📞 薛先生 0912877583（同 LINE）\nLINE：https://line.me/ti/p/kg1pMk4vX8\n\n—\n凱璿誼峰不動產有限公司\n經紀業特許字號：高市地政籍字第11034791100號\n證照字號：（111）登字第417208號';
const 社團footer = '\n\n—\n凱璿誼峰不動產有限公司｜薛先生 0912877583\n經紀業特許字號：高市地政籍字第11034791100號';
const 粉專文案 = body + 粉專footer;
const grpBody = String(parsed['社團主體'] || '').trim();
const 社團文案 = grpBody + 社團footer;
return [{ json: { ...src, 粉專文案, 社團文案, _copyRescued: 救援, _主體長度: { fb: body.length, grp: grpBody.length } } }];

// 把 Notion 那邊的 pageId / 舊貼文 id 併回文案流
const ctx = $('挑一件重發').first().json;
return [{ json: { ...$input.first().json, ...ctx } }];

const fbids = $input.all().map(i => i.json?.id).filter(Boolean).slice(0, 10);
const ctx = $('補上下文').first().json;
return [{ json: { ...ctx, fbids } }];

const resp = $input.first().json;
const id = resp.id || resp.post_id || '';
const ctx = $('收集 media id').first().json;
const parts = String(id).split('_');
const permalink = id ? (parts.length === 2 ? `https://www.facebook.com/${parts[0]}/posts/${parts[1]}` : `https://www.facebook.com/${id}`) : '';
return [{ json: { ...ctx, fbPostId: id, permalink } }];

// 永慶官網補資料 v5（2026-08-01 加撞號防線：編號數字對上還要行政區＋佐證；土地案佐證用地坪/地段名）
// 比對＝**物件編號對物件編號**，一把鑰匙一道鎖：
//   官網每個物件頁的 JSON-LD 裡有 "productID"，例 KEIS 的 PG0092558 → 官網寫 YC0092558、
//   EG0501408 → TC0501408（YC=永慶、TC=台慶、YE=永義，字母前綴各家不同，**數字部分完全一致**）。
//   所以只比數字，字母一律砍掉。
// 為什麼還要「逐筆檢查」而不是直接取搜尋結果第一筆：官網搜尋結果的 JSON-LD 第一筆 url 是壞的，
//   永遠寫成 house/4308114（台北信義區的某物件），第二筆才是真的。搜「0092558」「0501408」
//   「橋都路」「交響樂」第一筆都是它。取第一筆＝每次都接到同一個不相干的物件頁。
// 備援（只在候選頁面全都讀不到 productID 時才啟用，＝官網改版拿掉了這個欄位）：
//   舊的「識別（案名／社區／路名）+ 佐證（總價／權狀坪／建物坪）」評分。留著是為了官網改版時
//   整條線不會直接停擺，但有 productID 就一律以 productID 為準，對不上就是沒有，不猜。
// 補回：屋齡、學區；並交叉驗證格局樓層，不一致就留白
const UA = { 'user-agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/126 Safari/537.36', 'accept-language': 'zh-TW,zh;q=0.9' };
const http = (opt) => this.helpers.httpRequest(opt);
const results = [];

// 2026-07-26 使用者要求：官網查無學區/屋齡時，別讓 Gemini 看到 KEIS 賣點裡提到的相關字句——
// 賣點常見「近學區」這類寫法，屬實但官網沒登記，靠事後的數字守門員整篇擋掉太浪費（AG1927883
// 就是撞到這個：文案照賣點原文寫「近學區」，官網學區欄空白，整篇被判「腦補」打回，Notion 連
// 列都不會建，若無候補接棒下一班還會再抓到同一件、再擋一次）。從源頭砍掉這類子句，Gemini 就
// 沒有材料能寫，比事後擋掉一整篇文案更好；標題也是由賣點素材延伸，砍了子句標題自然也不會提到。
const stripTopic = (text, re) => String(text || '')
  .split(/([，。、\s])/)
  .filter((seg, i) => !(i % 2 === 0 && re.test(seg)))
  .join('')
  .replace(/^[，。、\s]+/, '')
  .replace(/[，、]{2,}/g, '，')
  .replace(/[，、]\s*(?=。|$)/g, '')
  .trim();

const norm = s => String(s || '').replace(/[\s\u3000|｜,，、。．・~～\-－—_()（）\[\]【】*＊]/g, '');
const onlyDigits = s => String(s || '').replace(/^[A-Za-z]+/, '').trim();

const searchList = async (city, kw) => {
  if (!kw) return [];
  try {
    const listUrl = `https://buy.yungching.com.tw/list/${encodeURIComponent(city)}-_c/${encodeURIComponent(kw)}_kw`;
    const html = String(await http({ url: listUrl, json: false, timeout: 20000, headers: UA }));
    for (const m of html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)) {
      let d; try { d = JSON.parse(m[1]); } catch (e) { continue; }
      if (d['@type'] === 'ItemList' && Array.isArray(d.itemListElement)) {
        return [...new Set(d.itemListElement.map(e => String(e.url || '')).filter(u => /\/house\/\d+/.test(u)))];
      }
    }
  } catch (e) {
    // 官網搜不到東西時是直接回 404，不是錯誤，當成沒候選就好
  }
  return [];
};

for (const item of $input.all()) {
  const src = item.json;
  const out = { ycUrl: '', ycHouseId: '', ycNote: '', ycMatch: '', 屋齡: null, 學區: '', 格局: src['格局'] || '', 樓層: src['樓層'] || '', 交叉檢查: [] };
  try {
    const key = onlyDigits(src.contract_no);           // KEIS 編號的數字部分＝鑰匙
    const city = (String(src['地址'] || '').match(/^(.{1,3}?[縣市])/) || [])[1] || '高雄市';
    const road = String(src['路名'] || '').replace(/[0-9０-９]+.*$/, '').trim();   // 路名去掉門牌號
    const district = String(src['行政區'] || '').trim();          // 撞號防線用（見下方候選迴圈註解）
    const community = String(src['社區'] || '').trim();
    const caseName = norm(src['案名']);
    const price = Number(src['總價萬']) || 0;
    const area = Number(src['建物坪']) || 0;
    const regArea = Number(src['權狀坪']) || 0;
    const landArea = Number(src['地坪']) || 0;      // 土地案用
    const lot = String(src['地段'] || '').trim();    // 土地案用（如「姑山段」）

    let via = '編號搜尋';
    let cands = await searchList(city, key);
    if (!cands.length && community) { cands = await searchList(city, community); via = '社區名搜尋'; }

    let hit = null, backup = null, sawProductId = false; const why = [], collision = [];
    for (const u of cands.slice(0, 8)) {
      let p;
      try { p = String(await http({ url: u, json: false, timeout: 20000, headers: UA })); } catch (e) { continue; }
      const houseId = (u.match(/\/house\/(\d+)/) || [])[1] || '';

      const t = p.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
      const tn = t.replace(/[,，\s]/g, '');   // 去逗號空白，官網價格寫成「1,150 萬」
      const title = ((p.match(/<title>([\s\S]*?)<\/title>/) || [])[1] || '');

      // 佐證材料（撞號防線與備援評分共用）
      const districtOk = district.length >= 2 && tn.includes(district);
      const priceOk = price > 0 && tn.includes(price + '萬');
      const m2 = (tn.match(/建物[^0-9]{0,6}([0-9]+(?:\.[0-9]+)?)坪/) || [])[1];
      const regOk = regArea > 0 && m2 && Math.abs(Number(m2) - regArea) <= 0.5;
      const areaOk = area > 0 && m2 && Math.abs(Number(m2) - area) <= 0.5;
      // 土地案：沒有「建物坪」可比（KEIS 那欄是 0），改用官網的「土地 XX 坪」＋地段名。
      // 2026-08-01 拿 4 筆土地案實測：地坪 4/4、地段名 4/4 都對得上，比只靠總價紮實。
      const m3 = (tn.match(/土地[^0-9]{0,6}([0-9]+(?:\.[0-9]+)?)坪/) || [])[1];
      const landOk = landArea > 0 && m3 && Math.abs(Number(m3) - landArea) <= 0.5;
      const lotOk = lot.length >= 2 && tn.includes(lot);
      const 佐證Ok = priceOk || regOk || areaOk || landOk || lotOk;

      // ── 主要：物件編號精準比對
      const rawPid = ((p.match(/"productID"\s*:\s*"([^"]+)"/) || [])[1] || '');
      const pid = onlyDigits(rawPid);
      if (rawPid) sawProductId = true;
      if (pid && key && (pid === key || Number(pid) === Number(key))) {
        // ⚠️ 2026-08-01 教訓：數字一樣不代表同一件。各品牌（YC永慶／TC台慶／YE永義）各自發號，
        //    數字部分會撞號——LA0067094（大樹區土地）就比中了 YE0067094（新北淡水的別人家），
        //    廣告連結因此指到不相干的物件，而且一路過關沒人擋。
        //    所以「編號數字對上」只是必要條件，還要行政區 + （總價或坪數）都對得上才算命中。
        //    現有 50 筆正確配對實測：行政區 50/50、總價 50/50 都通過，這道關卡不會誤擋；
        //    坪數單獨當門檻會誤擋土地類 4 筆（土地沒有「建物坪」），所以只當佐證之一、不強制。
        if (districtOk && 佐證Ok) {
          hit = { url: u, page: p, tag: `${houseId} 編號 ${rawPid}＝${src.contract_no}／區O${priceOk ? '價O' : ''}${(regOk || areaOk) ? '坪O' : ''}${landOk ? '地坪O' : ''}${lotOk ? '地段O' : ''}` };
          break;
        }
        collision.push(`${houseId}(${rawPid})區${districtOk ? 'O' : 'X'}價${priceOk ? 'O' : 'X'}坪${(regOk || areaOk) ? 'O' : 'X'}地坪${landOk ? 'O' : 'X'}地段${lotOk ? 'O' : 'X'}`);
        why.push(`${houseId}:編號${rawPid}對上但佐證不符→判定撞號，不採用`);
        continue;
      }

      // ── 備援材料：官網若哪天拿掉 productID，才會用到
      const nameOk = caseName.length >= 6 && norm(title).includes(caseName);
      const commOk = community.length >= 2 && tn.includes(community);
      const roadOk = road.length >= 2 && tn.includes(road);
      const idScore = (nameOk ? 3 : 0) + (commOk ? 2 : 0) + (roadOk ? 2 : 0);
      const numScore = (priceOk ? 2 : 0) + (regOk ? 1 : 0) + (areaOk ? 1 : 0) + (landOk ? 2 : 0) + (lotOk ? 2 : 0);
      const tag = `${houseId}:編號${rawPid || '無'} 名${nameOk ? 'O' : 'X'}社${commOk ? 'O' : 'X'}路${roadOk ? 'O' : 'X'}區${districtOk ? 'O' : 'X'}價${priceOk ? 'O' : 'X'}坪${(regOk || areaOk) ? 'O' : 'X'}`;
      // 備援路徑也一律要求行政區對得上，理由同上（撞號）
      if (districtOk && idScore > 0 && numScore > 0 && (!backup || idScore + numScore > backup.score)) {
        backup = { url: u, page: p, score: idScore + numScore, tag };
      }
      why.push(tag);
    }

    // 有 productID 可讀就一律以它為準；只有整批都讀不到（官網改版）才准用備援
    let best = hit;
    if (!best && !sawProductId && backup) best = backup;

    if (!best) {
      out.ycNote = collision.length
        ? `⚠️編號撞號擋下：官網有同號物件，但行政區/總價/坪數都對不上，判定不是同一件（${collision.join(' ')}）`
        : (cands.length
          ? `候選 ${cands.length} 筆都不是這件（${via}：${why.join(' ')}）`
          : `官網查無此編號（搜 ${key}${community ? '、社區 ' + community : ''}）`);
    } else {
      out.ycUrl = best.url;
      out.ycHouseId = (best.url.match(/\/house\/(\d+)/) || [])[1] || '';
      out.ycNote = 'ok';
      out.ycMatch = hit ? `${via}／${best.tag}` : `⚠️備援比對（官網讀不到編號欄位）／${via}／${best.tag}`;
      const t = best.page.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
      const age = (t.match(/屋齡\s*([0-9.]{1,5})\s*年/) || [])[1];
      if (age) out['屋齡'] = Math.round(Number(age));
      out['學區'] = [...new Set((t.match(/[一-龥]{2,6}(?:國小|國中)/g) || [])
        .map(s => s.replace(/^(近|鄰|臨|旁|到|往)/, '')))].filter(s => s.length >= 3).slice(0, 3).join('、');
      const ycLayout = (t.match(/([0-9]+房[0-9]+廳[0-9]+衛)/) || [])[1] || '';
      // ⚠️ 官網樓層寫成「1~3/17樓」，分隔號是波浪號不是減號，抓錯會把 1~3 切成 3
      const ycFloor = ((t.match(/([0-9B]{1,3}(?:\s*[-~～－]\s*[0-9B]{1,3})?\s*\/\s*[0-9]{1,3})\s*樓/) || [])[1] || '').replace(/\s+/g, '');
      const eq = (a, b) => String(a).replace(/\s+/g, '').replace(/[~～－]/g, '-') === String(b).replace(/\s+/g, '').replace(/[~～－]/g, '-');
      // 2026-08-04 教訓：LA0067094（土地案）比中撞號物件時，樓層 10/13 從別間房子洩漏進來——
      // 土地/車位本來就不該有格局／樓層，不管官網比對到什麼，一律不准填回去。
      const isLand = /土地|農|廠|車位/.test(String(src['建物類型'] || ''));
      if (!isLand && ycLayout && src['格局']) {
        if (!eq(ycLayout, src['格局'])) { out['格局'] = ''; out['交叉檢查'].push(`格局不一致(KEIS ${src['格局']} / 官網 ${ycLayout})`); }
      } else if (!isLand && ycLayout && !src['格局']) { out['格局'] = ycLayout; }
      if (!isLand && ycFloor && src['樓層']) {
        if (!eq(ycFloor, src['樓層'])) { out['樓層'] = ''; out['交叉檢查'].push(`樓層不一致(KEIS ${src['樓層']} / 官網 ${ycFloor})`); }
      } else if (!isLand && ycFloor && !src['樓層']) { out['樓層'] = ycFloor; }
    }
  } catch (e) {
    out.ycNote = '查詢失敗：' + (e.message || e);
  }
  // ⚠️ 查不到就留空，不要拿 houseol 網址頂替（KEIS 廣告追蹤只收永慶/台慶連結，頂替會被打槍）
  // 查不到的下場＝這件整件跳過、換候補下一件，見下游的「有永慶連結?」門檻

  // 官網沒有學區/屋齡就把賣點裡對應的子句砍掉，別讓 Gemini 有機會照抄進文案（見上方 2026-07-26 註解）
  let sellingPoints = src['賣點'] || [];
  if (!out['學區']) sellingPoints = sellingPoints.map(t => stripTopic(t, /學區|國小|國中/));
  if (out['屋齡'] == null) sellingPoints = sellingPoints.map(t => stripTopic(t, /屋齡|年新|新成屋|中古/));
  out['賣點'] = sellingPoints.filter(Boolean);

  results.push({ json: { ...src, ...out } });
}
return results;

// 數字守門員 v2：
// (1) 文案裡的每個數字都要在官方事實裡找得到
// (2) 官方沒有的欄位（屋齡/學區），文案裡連提都不准提——擋 AI 自己腦補
const j = $input.first().json;

const facts = new Set();
const push = v => {
  if (v === null || v === undefined || v === '') return;
  const n = String(v).replace(/,/g, '');
  facts.add(n);
  if (/^\d+\.\d+$/.test(n)) { facts.add(String(Math.round(Number(n)))); facts.add(n.split('.')[0]); }
  if (/^\d+$/.test(n)) facts.add(String(Number(n)));
};
[j['總價萬'], j['單價'], j['主建坪'], j['建物坪'], j['屋齡']].forEach(push);
const raw = [j['格局'], j['樓層'], j['地址'], j['案名'], j['社區'], j['車位'], j['學區'],
  ...(j['賣點'] || []), ...Object.values(j['機能'] || {})].join(' ');
(raw.match(/\d+(?:\.\d+)?/g) || []).forEach(push);
['0912877583', '11034791100', '417208', '111'].forEach(push);
// 降價重發時，文案會多出「舊價」和「降幅」兩個數字，它們的出處是 Notion 上一版與 KEIS 現價，
// 不是 AI 掰的，要放行；但「殘留舊價」（該換沒換到）仍然要擋。
const dz = j['_降價'];
if (dz) { [dz['舊價'], dz['新價'], dz['降幅']].forEach(push); }

const fb = String(j['粉專文案'] || '');
const grp = String(j['社團文案'] || '');
const body = fb + '\n' + grp;

// (1) 數字檢查（先把網址拿掉，LINE 連結的亂碼裡有數字，不是文案在講的數字）
const scan = body.replace(/https?:\/\/\S+/g, ' ');
const used = [...new Set((scan.match(/\d+(?:\.\d+)?/g) || []))];
let badNums = used.filter(n => !facts.has(n) && !facts.has(String(Number(n))));

// (2) 沒資料就不准提
let banned = [];
if (j['屋齡'] === null || j['屋齡'] === undefined || j['屋齡'] === '') {
  if (/屋齡|年新|新成屋|中古/.test(body)) banned.push('屋齡（官方沒這筆資料）');
}
if (!j['學區']) {
  if (/學區|國小|國中/.test(body)) banned.push('學區（官方沒這筆資料）');
}
if (!j['格局'] && /\d+房\d+廳/.test(body)) banned.push('格局（官方沒這筆資料）');
if (!j['樓層'] && /\d+\s*\/\s*\d+\s*樓|樓層/.test(body)) banned.push('樓層（官方沒這筆資料）');

// 降價重發是拿「上一版已經過守門員的文案」原封不動改價，只有降價那句是新的。
// 若拿今天的 KEIS／官網資料回頭重審整篇，只要官網又砍欄位（砍過不只一次）就會誤擋一篇合法的重發。
// 所以這裡改成只審「這一版新冒出來的東西」：舊文案本來就有的數字與描述視同已審過，
// 真正該擋的「價格沒換乾淨」由 _降價.殘留舊價 獨立把關，不受這段放寬影響。
if (dz) {
  const 舊數 = new Set(((String(dz['舊文'] || '').replace(/https?:\/\/\S+/g, ' ')).match(/\d+(?:\.\d+)?/g) || []));
  badNums = badNums.filter(n => !舊數.has(n) && !舊數.has(String(Number(n))));
  banned = [];
}

const ctx = n => {
  const i = body.indexOf(n);
  return i < 0 ? '' : body.slice(Math.max(0, i - 12), i + 12).replace(/\n/g, ' ');
};
// (3) 出貨前形狀檢查（2026-08-03 加）：
// AI 回傳格式壞掉時，整包 JSON 會被當文案發出去。這裡是最後一道，寧可不發也不要貼垃圾。
const len = j['_主體長度'] || {};
const 殘骸 = [];
if (/"粉專主體"|"社團主體"|\\n|```/.test(body)) 殘骸.push('文案裡有 JSON／程式殘骸，AI 回傳格式壞掉');
if (typeof len.fb === 'number' && len.fb < 60) 殘骸.push(`粉專主體只有 ${len.fb} 字，不像正常文案`);
if (typeof len.grp === 'number' && len.grp < 15) 殘骸.push(`社團主體只有 ${len.grp} 字，不像正常文案`);
if (dz && dz['殘留舊價']) 殘骸.push(`降價重發但文案裡還看得到舊價 ${dz['舊價']} 萬，價格沒換乾淨`);

const ok = badNums.length === 0 && banned.length === 0 && 殘骸.length === 0;
const msg = ok ? '' :
  `⚠️ ${j.contract_no} 這篇沒發，文案沒過檢查：\n` +
  (badNums.length ? `・查無出處的數字：${badNums.map(n => `${n}（…${ctx(n)}…）`).join('；')}\n` : '') +
  (banned.length ? `・不該提的項目：${banned.join('、')}\n` : '') +
  (殘骸.length ? `・文案本身壞掉：${殘骸.join('、')}\n` : '') +
  `Notion 沒有建列，要發請手動處理。`;

return [{ json: { ...j, _guardOk: ok, _guardBad: badNums, _guardBanned: banned, _guardJunk: 殘骸, _guardMsg: msg } }];

// 解壓後所有照片在同一筆的多個 binary 欄位裡，拆成一筆一張，最多 10 張（FB 單篇上限）
const item = $input.first();
const bin = item.binary || {};
const keys = Object.keys(bin).sort((a, b) => String(bin[a].fileName || a).localeCompare(String(bin[b].fileName || b), 'en', { numeric: true }));
const pick = keys.filter(k => /image\//.test(bin[k].mimeType || '')).slice(0, 10);
if (!pick.length) return [];
return pick.map((k, i) => ({ json: { idx: i, fileName: bin[k].fileName }, binary: { photo: bin[k] } }));

// 降價重發：不叫 AI 重寫，沿用上一版文案原文，只做兩件事——
//   ① 文案裡的舊價全部換成新價 ② 標題底下插一行降價說明
// 為什麼不重新產：使用者要的就是「同一篇、只差那一句」；而且 Gemini 免費配額每天只有 20 次
// （見 STATUS 0.5），能省一次是一次。順帶好處是不會有 AI 亂寫的風險。
const src = $input.first().json;                 // 永慶官網補資料 的輸出，總價萬 已是 KEIS 現價
const ctx = $('挑一件重發').first().json;
const oldP = Number(ctx['舊總價萬'] || 0);
const newP = Number(src['總價萬'] || 0);
const drop = Math.round((oldP - newP) * 10) / 10;

// 舊文案寫價格的方式有「1298萬」「1298 萬」「1,298萬」好幾種。
// 先把千分位逗號拿掉統一成一種寫法再換，不然漏掉一種就是掛著舊價發出去。
const denorm = t => String(t || '').replace(/(\d),(?=\d{3}(?!\d))/g, '$1');
const swap = t => denorm(t)
  .split(oldP + ' 萬').join(newP + ' 萬')
  .split(oldP + '萬').join(newP + '萬');

const dropLine = '🔻 降價 ' + drop + ' 萬（' + oldP + ' 萬 → ' + newP + ' 萬）';

// 粉專版：第一行是【】標題，降價那句插在標題正下方，最顯眼又不會擋到標題
let fb = swap(ctx['舊粉專文案']);
const lines = fb.split('\n');
lines.splice(1, 0, dropLine);
fb = lines.join('\n');

// 社團版本來就不寫具體價格，所以降價這句放最前面當開頭
const grp = dropLine + '\n' + swap(ctx['舊社團文案']);

// 防呆：換完還看得到舊價（且不是降價那句裡的），代表舊文案的價格寫法沒被涵蓋到
// → 標記起來交給守門員擋下，寧可不發也不要掛錯價格
const 掃描 = denorm(fb + ' ' + grp).split(dropLine).join(' ');
const 殘留舊價 = new RegExp('(?:^|[^0-9])' + oldP + '\\s*萬').test(掃描);

return [{ json: { ...src, 粉專文案: fb, 社團文案: grp,
  _降價: { 舊價: oldP, 新價: newP, 降幅: drop, 殘留舊價,
          舊文: String(ctx['舊粉專文案'] || '') + ' ' + String(ctx['舊社團文案'] || '') },
  _主體長度: { fb: fb.length, grp: grp.length } } }];
